// scripts/migrate-uuid-truncation.js
//
// ONE-OFF migration: truncates full-length (36-char) player uuids down to a
// 10-char prefix (see scripts/lib/uuid-prefix.cjs) inside existing
// games/bv/{sid}.json files — the fields touched are g.games[gameId].p[].id,
// g.games[gameId].hp[].profileID, g.games[gameId].ap[].profileID.
//
// Why games/ needs a dedicated migration and the other three directories
// touched by the wider UUID-storage migration don't:
//   - leaderboard/  → fully regenerated by `node scripts/build-leaderboards.js --force`
//   - team-stats/   → fully regenerated by `node scripts/build-team-stats.js`
//   - search/       → fully regenerated by `node scripts/build-search-index.js`
//   All three of those scripts already write truncated ids as of the
//   2026-07-10 uuid-storage-migration update — a full rebuild naturally
//   truncates everything, no bespoke migration logic needed or wanted (it
//   would just duplicate/risk drifting from the real build logic).
//   games/bv/*.json has no equivalent regeneration path: nightly-crawl.js
//   only ever writes p[].id for NEW games going forward, and — a finding
//   from reading nightly-crawl.js in full during this same migration work —
//   no current code path writes hp[]/ap[] to game files AT ALL anymore, so
//   existing hp/ap data is frozen exactly as historical crawls left it.
//   This script is therefore the only way existing games/bv/*.json data
//   ever gets truncated.
//
// Only actually-full-length (36-char) values are truncated — anything
// already short is left untouched (idempotent: safe to re-run, safe to
// resume after an interruption).
//
// Progress tracks completed season ids only — each file is fully rewritten
// or fully left alone, never partially modified across runs.
//
// Run:     node scripts/migrate-uuid-truncation.js
// Dry run: node scripts/migrate-uuid-truncation.js --dry-run
// Force:   node scripts/migrate-uuid-truncation.js --force   (ignore progress, start over)

'use strict';

const fs           = require('fs');
const path         = require('path');
const { execSync } = require('child_process');
const { truncateUuid, isFullUuid } = require('./lib/uuid-prefix.cjs');

const ROOT          = path.join(__dirname, '..');
const GAMES_DIR     = path.join(ROOT, 'games', 'bv');
const DRY_RUN       = process.argv.includes('--dry-run');
const FORCE         = process.argv.includes('--force');
const COMMIT_EVERY  = 100; // season files per commit
const PROGRESS_FILE = path.join(ROOT, 'scripts', '.migrate-uuid-truncation-progress.json');

function readJson(p) { return JSON.parse(fs.readFileSync(p, 'utf8')); }
function writeJson(p, d) { fs.writeFileSync(p, JSON.stringify(d), 'utf8'); }

function gitCommit(message) {
  if (DRY_RUN) { console.log(`  [dry-run] would commit: ${message}`); return; }
  try {
    execSync('git add games/ scripts/.migrate-uuid-truncation-progress.json',
      { stdio: 'pipe', cwd: ROOT, maxBuffer: 512 * 1024 * 1024 });
    const staged = execSync('git diff --staged --shortstat',
      { stdio: 'pipe', cwd: ROOT, maxBuffer: 10 * 1024 * 1024 }).toString().trim();
    if (!staged) { console.log('  Nothing to commit.'); return; }
    execSync(`git commit -q -m "${message}"`, { stdio: 'pipe', cwd: ROOT });
    execSync('git fetch origin main',                            { stdio: 'pipe', cwd: ROOT });
    execSync('git merge -X ours FETCH_HEAD --no-edit --no-stat', { stdio: 'pipe', cwd: ROOT });
    execSync('git push origin main',                             { stdio: 'pipe', cwd: ROOT });
    console.log(`  ✓ Committed: ${message}`);
  } catch (e) {
    console.error('  git error:', e.stderr?.toString().slice(0, 300) || e.message.slice(0, 300));
  }
}

// Truncates a single field in place if (and only if) it's currently a
// full-length uuid. Returns true if it changed anything.
function truncateField(obj, field) {
  const v = obj[field];
  if (!isFullUuid(v)) return false;
  obj[field] = truncateUuid(v);
  return true;
}

function migrateGameFile(gf) {
  let changed = 0;
  for (const game of Object.values(gf.games || {})) {
    for (const p of (game.p || []))  if (truncateField(p, 'id'))         changed++;
    for (const p of (game.hp || [])) if (truncateField(p, 'profileID'))  changed++;
    for (const p of (game.ap || [])) if (truncateField(p, 'profileID'))  changed++;
  }
  return changed;
}

function main() {
  const startTime = Date.now();
  console.log('migrate-uuid-truncation.js');
  if (DRY_RUN) console.log('  ⚠  DRY RUN — no writes or commits');
  console.log('─'.repeat(60));

  let progress = { doneSids: [] };
  if (FORCE) {
    console.log('  --force: starting fresh\n');
  } else if (fs.existsSync(PROGRESS_FILE)) {
    try { progress = readJson(PROGRESS_FILE); } catch {}
  }
  const doneSids = new Set(progress.doneSids ?? []);

  const allSids = fs.readdirSync(GAMES_DIR).filter(f => f.endsWith('.json')).map(f => f.replace('.json', '')).sort();
  const pendingSids = allSids.filter(s => !doneSids.has(s));
  console.log(`  ${allSids.length} season files | ${doneSids.size} already done | ${pendingSids.length} remaining`);

  let filesModified = 0, filesUnchanged = 0, idsTruncated = 0, sinceCommit = 0;

  for (const sid of pendingSids) {
    const fpath = path.join(GAMES_DIR, `${sid}.json`);
    let gf;
    try { gf = readJson(fpath); }
    catch (e) { console.error(`  ✗ failed to read ${sid}.json: ${e.message}`); doneSids.add(sid); continue; }

    const changed = migrateGameFile(gf);
    if (changed > 0) {
      if (!DRY_RUN) fs.writeFileSync(fpath, JSON.stringify(gf), 'utf8');
      filesModified++;
      idsTruncated += changed;
    } else {
      filesUnchanged++;
    }

    doneSids.add(sid);
    sinceCommit++;

    if (sinceCommit >= COMMIT_EVERY) {
      if (!DRY_RUN) {
        writeJson(PROGRESS_FILE, { doneSids: [...doneSids] });
        gitCommit(`migrate-uuid-truncation: ${doneSids.size}/${allSids.length} season files done, ${idsTruncated.toLocaleString()} ids truncated`);
      }
      sinceCommit = 0;
      console.log(`  ${doneSids.size}/${allSids.length} seasons done — ${filesModified} modified, ${idsTruncated.toLocaleString()} ids truncated`);
    }
  }

  if (!DRY_RUN && sinceCommit > 0) {
    writeJson(PROGRESS_FILE, { doneSids: [...doneSids] });
    gitCommit(`migrate-uuid-truncation: complete — ${filesModified} files modified, ${idsTruncated.toLocaleString()} ids truncated`);
  }

  if (!DRY_RUN && fs.existsSync(PROGRESS_FILE)) {
    fs.unlinkSync(PROGRESS_FILE);
    gitCommit('migrate-uuid-truncation: remove progress file');
  }

  const elapsed = Math.round((Date.now() - startTime) / 1000);
  console.log('\n' + '─'.repeat(60));
  console.log(`  Season files scanned  : ${allSids.length}`);
  console.log(`  Season files modified : ${filesModified}`);
  console.log(`  Season files unchanged: ${filesUnchanged}`);
  console.log(`  Ids truncated (total) : ${idsTruncated.toLocaleString()}`);
  console.log(`  Elapsed               : ${elapsed}s`);
  console.log(`  Mode                  : ${DRY_RUN ? 'DRY RUN' : 'LIVE'}`);
  console.log('─'.repeat(60));
  console.log('\nNext steps (regenerate the other 3 truncated directories):');
  console.log('  node scripts/build-leaderboards.js --force');
  console.log('  node scripts/build-team-stats.js');
  console.log('  node scripts/build-search-index.js');
}

main();
